<script>
(()=>{const RM=matchMedia("(prefers-reduced-motion: reduce)").matches;
const vis=e=>e&&e.offsetParent!==null;
const ptr=z=>{const p=z.querySelector(":scope>.appt");if(!p||RM||!z.offsetWidth)return;const D=+z.dataset.d||8,R=z.getBoundingClientRect();
const pts=z.dataset.p.split(",").map(x=>{const [sel,pc]=x.split("@");const e=z.querySelector(sel);if(!e)return null;const r=e.getBoundingClientRect();return[r.left-R.left+r.width*.5,r.top-R.top+r.height*.55,+pc]}).filter(Boolean);if(!pts.length)return;
const id="app"+Math.round(R.width)+"x"+Math.round(R.height)+"x"+pts.map(q=>Math.round(q[0])+"_"+Math.round(q[1])).join("_");if(p.dataset.k===id)return;p.dataset.k=id;
const S=[R.width*.92,R.height+12],T=(q,s)=>`transform:translate(${q[0].toFixed(1)}px,${q[1].toFixed(1)}px)${s?" scale("+s+")":""}`;
let k=`0%{${T(S)};opacity:0}`,prev=0;
pts.forEach((q,i)=>{const a=q[2];if(i===0)k+=`${Math.max(3,a-20)}%{${T(S)};opacity:1}`;else{const h=Math.max(prev+4,a-14);if(h>prev)k+=`${h}%{${T(pts[i-1])}}`}k+=`${a}%{${T(q)}}${a+1}%{${T(q,.8)}}${a+2.5}%{${T(q)}}`;prev=a+2.5});
const L=pts[pts.length-1];k+=`${Math.min(prev+8,88)}%{${T(L)};opacity:1}${Math.min(prev+18,96)}%{${T(S)};opacity:0}100%{${T(S)};opacity:0}`;
let st=z.querySelector(":scope>style.appk");if(!st){st=document.createElement("style");st.className="appk";z.appendChild(st)}st.textContent=`@keyframes ${id}{${k}}`;p.style.animation=`${id} ${D}s cubic-bezier(.45,0,.2,1) infinite`};
const apd=()=>document.querySelectorAll(".apmb").forEach(z=>{const d=z.querySelector(".apdrag"),s=z.querySelector(".apsrc"),t=z.querySelector(".aptgt");if(!d||!s||!t||!z.offsetWidth)return;const Z=z.getBoundingClientRect(),S=s.getBoundingClientRect(),T=t.getBoundingClientRect();const v={"--fx":S.left-Z.left,"--fy":S.top-Z.top,"--tx":T.left-Z.left+T.width/2-S.width/2,"--ty":T.top-Z.top+T.height/2-S.height/2,"--sw":S.width,"--sh":S.height};for(const k in v)d.style.setProperty(k,v[k].toFixed(1)+"px")});
const fit=()=>{apd();document.querySelectorAll(".appz[data-p]").forEach(ptr)};
const typer=w=>{const el=w.querySelector(".apty[data-t]");if(!el)return;const t=el.dataset.t,sp=t.length<24?110:40;w.classList.add("js");if(RM){w.classList.add("done");return}let i=0;el.textContent="";
const tick=()=>{if(!vis(el)){i=0;el.textContent="";w.classList.remove("done");return setTimeout(tick,600)}if(i<=t.length){el.textContent=t.slice(0,i);i++;if(i>t.length){w.classList.add("done");setTimeout(tick,4200)}else setTimeout(tick,sp+Math.random()*sp)}else{i=0;el.textContent="";w.classList.remove("done");setTimeout(tick,800)}};setTimeout(tick,900)};
const typer2=el=>{const t=el.dataset.t;if(RM)return;let i=0;el.textContent="";const tick=()=>{if(!vis(el)){i=0;el.textContent="";return setTimeout(tick,700)}if(i<=t.length){el.textContent=t.slice(0,i);i++;setTimeout(tick,i>t.length?2800:75)}else{i=0;el.textContent="";setTimeout(tick,900)}};setTimeout(tick,2600)};
const ghost=()=>document.querySelectorAll(".apty[data-t],.apty2[data-t]").forEach(el=>{const p=el.parentElement;if(p.classList.contains("apgr"))return;const l=document.createElement("span");l.className="apwrt";const c=el.nextElementSibling&&el.nextElementSibling.classList.contains("caret")?el.nextElementSibling:null;p.insertBefore(l,el);l.appendChild(el);if(c)l.appendChild(c);const g=document.createElement("span");g.className="apghost";g.setAttribute("aria-hidden","true");g.textContent=el.dataset.t;p.appendChild(g);p.classList.add("apgr")});
document.addEventListener("DOMContentLoaded",()=>{ghost();fit();document.querySelectorAll(".aptyw").forEach(typer);document.querySelectorAll(".apty2[data-t]").forEach(typer2)});
addEventListener("load",fit);addEventListener("resize",fit);document.addEventListener("click",()=>setTimeout(fit,60));document.addEventListener("input",()=>setTimeout(fit,60));
if(document.fonts)document.fonts.ready.then(fit)})();
</script>
